// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != c.owner());
        bytes memory originalOwner = abi.encode(c.owner());
        vm.prank(caller);
        try c.transferOwnership(newOwner) { }
        catch { }
        assertTrue(abi.encode(c.owner()).length == originalOwner.length && keccak256(abi.encode(c.owner())) == keccak256(originalOwner));
    }
}
